const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const clean = (value, max = 1000) => String(value ?? '').trim().replace(/\s+/g, ' ').slice(0, max);
const cleanMultiline = (value, max = 2000) => String(value ?? '').replace(/\r\n/g, '\n').split('\n').map((line) => line.trim().replace(/[ \t]+/g, ' ')).join('\n').replace(/\n{3,}/g, '\n\n').trim().slice(0, max);
const refFromPageUrl = (value) => {
  try {
    const url = new URL(String(value || ''), 'https://wwc.best');
    const query = String(url.searchParams.get('ref') || '').trim().toLowerCase();
    if (query) return query;
    const host = url.hostname.toLowerCase();
    if (!host.endsWith('.wwc.best') || host === 'wwc.best' || host === 'www.wwc.best') return '';
    const sub = host.split('.')[0];
    if (sub === 'elena') return 'onlineelena';
    if (sub === 'samtsova') return 'olga-samtsova';
    return sub;
  } catch (e) {
    return '';
  }
};
const name = clean(body.name, 160);
const contact = clean(body.contact, 240);
const product = clean(body.product, 360);
const idempotency = clean(body.idempotency_key, 160);
const honey = clean(body.website, 160);
const fromUrl = refFromPageUrl(body.page_url || body.landing_url || '');
let firstRefCode = clean(body.initial_ref || body.first_ref || body.ref, 64).toLowerCase();
let activeRefCode = clean(body.active_ref || body.ref, 64).toLowerCase();
if (!activeRefCode) activeRefCode = fromUrl;
if (!firstRefCode) firstRefCode = fromUrl || activeRefCode;
const errors = [];
if (honey) errors.push('spam');
if (!name) errors.push('name');
if (!contact) errors.push('contact');
if (!product) errors.push('product');
if (!idempotency) errors.push('idempotency');
return [{ json: {
  valid: errors.length === 0,
  errors,
  tenant_id: 'whieda',
  name, contact, product_name: product,
  product_sku: clean(body.product_sku, 80),
  product_variant: clean(body.product_variant, 240),
  comment: cleanMultiline(body.comment, 2000),
  page_url: clean(body.page_url, 1000),
  first_ref_code: firstRefCode,
  active_ref_code: activeRefCode,
  idempotency_key: idempotency,
  country_code: ['RU', 'BY'].includes(clean(body.country_code, 2).toUpperCase()) ? clean(body.country_code, 2).toUpperCase() : 'RU',
  metadata: {
    referrer: clean(raw.headers?.referer, 1000),
    user_agent: clean(raw.headers?.['user-agent'], 500),
    routing_version: 'p0.4-site-owner',
    country_source: clean(body.country_source, 80)
  }
} }];

