with lead as (select * from website_leads where public_id='{{ String($json.public_id).replace(/'/g,'') }}' and tenant_id='whieda'), r as (
 select a.actor_id,a.telegram_chat_id,'owner' kind from lead l join lead_actors a on a.actor_id=l.assigned_owner_id
 union
 select a.actor_id,a.telegram_chat_id,'watcher' kind from lead l join lead_visibility_rules v on v.tenant_id=l.tenant_id and v.enabled and v.event_type='lead_created' and v.scope_type='owner' and v.scope_value=l.assigned_owner_id join lead_actors a on a.actor_id=v.watcher_actor_id
), d as (insert into lead_delivery_attempts(lead_id,tenant_id,event_type,recipient_actor_id,delivery_mode,status) select l.lead_id,l.tenant_id,'lead_created',r.actor_id,'full','pending' from lead l join r on true on conflict do nothing returning delivery_id,recipient_actor_id)
select d.delivery_id,r.actor_id,r.telegram_chat_id,r.kind,l.public_id,l.product_name,l.name,l.contact,l.comment,l.first_ref_code from d join r on r.actor_id=d.recipient_actor_id join lead l on true where r.telegram_chat_id is not null;

